def normalize_candidate_states(apps, schema_editor):
    User = apps.get_model('users', 'User')
    VolunteerVisit = apps.get_model('users', 'VolunteerVisit')

    # 1) Удаляем дубли визитов за один и тот же день, оставляем самый ранний id.
    seen = set()
    for visit in VolunteerVisit.objects.all().order_by('user_id', 'visit_date', 'id'):
        key = (visit.user_id, visit.visit_date)
        if key in seen:
            visit.delete()
            continue
        seen.add(key)

